-- Migration: Trivia - harder question mix
-- Purpose: 127 new questions (mostly difficulty 3: deep lore, 31-point talents, reagents, dungeon/raid
--          bosses, attunements and keys, quests, zone locations). Easy (difficulty 1) questions are switched
--          off except 8 fun ones; nothing is deleted (set active = true to bring one back).
-- Date: 2026-10-11
-- Reverse: UPDATE trivia_questions SET active = true WHERE difficulty = 1; delete the new questions.

ON CONFLICT (question) DO NOTHING;

UPDATE public.trivia_questions SET active = (question IN (
  'Hogger terrorizes which zone?', 'In which zone does the famous hunt for Mankrik''s wife take place?', 'What does a Hearthstone do?', 'Which item quality color represents Legendary items?', 'Which boss shouts "BY FIRE BE PURGED!"?', '"Many whelps! Handle it!" is a famous raid callout from which encounter?', 'Murlocs famously make which sound?', 'What do Orc peons famously say when given a job?'
))
WHERE difficulty = 1;
